"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useAuth } from "@/hooks/useAuth";

export default function LoginPage() {
  const router = useRouter();
  const { login, isAuthenticated, isLoading } = useAuth();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [apiError, setApiError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  // -------------------------
  // 副作用: 認証済みならトップへリダイレクト
  // -------------------------
  useEffect(() => {
    if (!isLoading && isAuthenticated) {
      router.push("/");
    }
  }, [isLoading, isAuthenticated, router]);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-900 text-white">
        <p>認証状態を確認中...</p>
      </div>
    );
  }

  if (isAuthenticated) return null; // リダイレクト済み

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setApiError("");
    setIsSubmitting(true);

    if (!email || !password) {
      setApiError("メールアドレスとパスワードを入力してください。");
      setIsSubmitting(false);
      return;
    }

    try {
      await login({ email, password });
      // 成功後は副作用でリダイレクト
    } catch (error: any) {
      let errorMessage = "ログインに失敗しました。再試行してください。";
      if (error.code) {
        switch (error.code) {
          case "auth/user-not-found":
          case "auth/wrong-password":
            errorMessage = "メールアドレスまたはパスワードが正しくありません。";
            break;
          case "auth/invalid-email":
            errorMessage = "メールアドレスの形式が正しくありません。";
            break;
          case "auth/too-many-requests":
            errorMessage = "短時間にログインが集中しています。";
            break;
          default:
            errorMessage = `ログインに失敗しました: ${error.message}`;
        }
      }
      setApiError(errorMessage);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    // 全体を画面中央に配置し、背景色を設定 (bodyのカスタムCSSをシミュレート)
    <div className="min-h-screen flex items-start sm:items-center justify-center bg-gray-50 pt-16 sm:pt-0">
      {/* ログインボックス: max-w-xl、p-8、bg-white、rounded-xl、shadow-2xlを適用 */}
      <div className="w-full max-w-md p-8 bg-white rounded-xl shadow-2xl mx-4 sm:mx-auto z-10 my-8">
        {/* タイトル: 中央寄せ、太字、下線付きの赤文字（元のデザインを参考に） */}
        <h2 className="text-center text-3xl font-extrabold text-gray-800 mb-6 border-b-2 border-red-100 pb-3">
          ログイン
        </h2>

        {/* エラーメッセージ: 元のデザインの赤色を使用 */}
        {apiError && (
          <div className="mb-6 p-4 bg-red-50 border border-red-300 text-red-700 rounded-lg text-sm font-medium transition duration-300">
            {apiError}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            {/* ラベル: 元のデザインのように太字に */}
            <label
              htmlFor="email"
              className="block text-sm font-bold text-gray-700 mb-2"
            >
              メールアドレス
            </label>
            <input
              id="email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              // フォームの幅を100%に、ボーダーとフォーカス時のリングを赤色に設定
              className="w-full px-4 py-2 border-2 border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-500 focus:border-red-500 transition duration-150 shadow-sm"
              required
              disabled={isSubmitting}
            />
          </div>

          <div>
            {/* ラベル: 元のデザインのように太字に */}
            <label
              htmlFor="password"
              className="block text-sm font-bold text-gray-700 mb-2"
            >
              パスワード
            </label>
            <input
              id="password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              // フォームの幅を100%に、ボーダーとフォーカス時のリングを赤色に設定
              className="w-full px-4 py-2 border-2 border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-500 focus:border-red-500 transition duration-150 shadow-sm"
              required
              disabled={isSubmitting}
            />
          </div>

          <div className="pt-4">
            {/* ログインボタン: 元のデザインの#ff5555に近い赤色（bg-red-600）と太字、シャドウを適用 */}
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-red-600 text-white py-3 rounded-lg font-bold text-lg 
                         hover:bg-red-700 transition duration-150 shadow-lg transform hover:scale-[1.01] 
                         disabled:bg-gray-400 disabled:cursor-not-allowed disabled:transform-none"
            >
              {isSubmitting ? (
                <>
                  <svg
                    className="animate-spin h-5 w-5 mr-3 inline-block"
                    viewBox="0 0 24 24"
                  >
                    <circle
                      className="opacity-25"
                      cx="12"
                      cy="12"
                      r="10"
                      stroke="currentColor"
                      strokeWidth="4"
                    ></circle>
                    <path
                      className="opacity-75"
                      fill="currentColor"
                      d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                    ></path>
                  </svg>
                  ログイン中...
                </>
              ) : (
                "ログインする"
              )}
            </button>
          </div>
        </form>

        {/* 会員登録リンク: Next.jsのLinkコンポーネントを標準のaタグに置き換え */}
        <div className="mt-8 text-center">
          <a
            href="/register" // Next.jsのルーティングURLをそのまま使用
            className="text-sm text-blue-600 hover:text-blue-800 transition duration-150 font-medium hover:underline"
          >
            会員登録はこちら
          </a>
        </div>
      </div>
    </div>
  );
}